{"path":"/app/test_aggregate_records.py","content":"import json
from pathlib import Path

from aggregate_records import aggregate_files


def write_records(path: Path, records: list[dict]) -> None:
    path.write_text("".join(json.dumps(record) + "\n" for record in records), encoding="utf-8")


def test_aggregates_users_tags_and_rounds_amounts(tmp_path: Path) -> None:
    first = tmp_path / "records_1.jsonl"
    second = tmp_path / "records_2.jsonl"
    write_records(
        first,
        [
            {"user": "bob", "amount": 1.005, "items": 2, "tags": ["z", "a"]},
            {"user": "alice", "amount": 10.10, "items": 3, "tags": ["a", "a"]},
        ],
    )
    write_records(
        second,
        [
            {"user": "bob", "amount": 2.005, "items": 4, "tags": ["a"]},
            {"user": "alice", "amount": 1, "items": 1, "tags": ["z"]},
        ],
    )

    result = aggregate_files([first, second])

    assert result == {
        "top_5_users_by_amount": {
            "alice": {"total_amount": 11.10, "total_items": 4},
            "bob": {"total_amount": 3.01, "total_items": 6},
        },
        "top_5_tags_by_count": {
            "a": {"count": 3},
            "z": {"count": 2},
        },
    }


def test_limits_results_and_breaks_ties_by_name(tmp_path: Path) -> None:
    path = tmp_path / "records_1.jsonl"
    records = [
        {"user": name, "amount": 1, "items": 1, "tags": [tag]}
        for name, tag in [("e", "e"), ("d", "d"), ("c", "c"), ("b", "b"), ("a", "a"), ("f", "f")]
    ]
    write_records(path, records)

    result = aggregate_files([path])

    assert list(result["top_5_users_by_amount"]) == ["a", "b", "c", "d", "e"]
    assert list(result["top_5_tags_by_count"]) == ["a", "b", "c", "d", "e"]
"}

